apriori_gen(L[k - 1]):
    C = empty set
    for each l1 in L[k - 1]:
        for each l2 in L[k - 1]:
            if l1[1..k-2] == l2[1..k-2] and l1[k-1] < l2[k-1]:
                c = join(l1, l2)
                if not has_infrequent_subset(c, L[k - 1]):
                    add c to C
    return C

has_infrequent_subset(c, L[k - 1]):
    for each (k - 1)-subset s of c:
        if s is not in L[k - 1]:
            return true
    return false
